-- HTML & CSS kurz — Kompletní kurz (Sekce 1-3 + kvízy + projekt + závěrečný kvíz)
-- MariaDB 10.4, phpMyAdmin style, no DELIMITER
-- Apostrofy escapovány jako ''

SET @kurs_id = (SELECT id FROM courses WHERE slug = 'html-css');

-- ============================================================
-- SEKCE 1: HTML základy (sort_order 1-10)
-- ============================================================

INSERT INTO lessons (course_id, title, content, lesson_type, sort_order, xp_reward, duration_minutes) VALUES
(@kurs_id, 'DOCTYPE a struktura dokumentu', '<h2>Struktura HTML dokumentu</h2><p>Každý HTML dokument začíná deklarací <code>&lt;!DOCTYPE html&gt;</code>, která říká prohlížeči, že jde o HTML5. Následuje kořenový element <code>&lt;html&gt;</code> s atributem <code>lang</code>, hlavička <code>&lt;head&gt;</code> a tělo <code>&lt;body&gt;</code>.</p><pre><code>&lt;!DOCTYPE html&gt;\n&lt;html lang="cs"&gt;\n&lt;head&gt;\n  &lt;meta charset="UTF-8"&gt;\n  &lt;meta name="viewport" content="width=device-width, initial-scale=1.0"&gt;\n  &lt;title&gt;Moje stránka&lt;/title&gt;\n&lt;/head&gt;\n&lt;body&gt;\n  &lt;h1&gt;Ahoj, VeVit!&lt;/h1&gt;\n&lt;/body&gt;\n&lt;/html&gt;</code></pre><p><code>meta charset</code> určuje kódování znaků (vždy UTF-8). <code>viewport</code> meta tag zajistí správné škálování na mobilních zařízeních — bez něj by se stránka na telefonu zobrazila zmenšeně.</p>', 'lesson', 1, 10, 10),

(@kurs_id, 'Sémantické tagy', '<h2>Sémantické HTML5 tagy</h2><p>Sémantické tagy dodávají obsahu význam — prohlížeč i vyhledávače díky nim rozumí struktuře stránky. Nikdy nepoužívej <code>&lt;div&gt;</code> pro vše.</p><pre><code>&lt;header&gt;\n  &lt;nav&gt;Navigace&lt;/nav&gt;\n&lt;/header&gt;\n&lt;main&gt;\n  &lt;article&gt;\n    &lt;section&gt;Sekce článku&lt;/section&gt;\n  &lt;/article&gt;\n  &lt;aside&gt;Postranní panel&lt;/aside&gt;\n&lt;/main&gt;\n&lt;footer&gt;Patička&lt;/footer&gt;</code></pre><p><code>&lt;header&gt;</code> — hlavička sekce/stránky, <code>&lt;nav&gt;</code> — navigace, <code>&lt;main&gt;</code> — hlavní obsah (jen 1x na stránku), <code>&lt;article&gt;</code> — samostatný obsah, <code>&lt;section&gt;</code> — tematická skupina, <code>&lt;aside&gt;</code> — vedlejší obsah, <code>&lt;footer&gt;</code> — patička.</p>', 'lesson', 2, 10, 10),

(@kurs_id, 'Nadpisy, odstavce a seznamy', '<h2>Nadpisy a text</h2><p>Nadpisy <code>&lt;h1&gt;</code> až <code>&lt;h6&gt;</code> tvoří hierarchii — <code>h1</code> jen jednou na stránku. Odstavce <code>&lt;p&gt;</code> obalují souvislý text.</p><pre><code>&lt;h1&gt;Hlavní nadpis&lt;/h1&gt;\n&lt;h2&gt;Podnadpis&lt;/h2&gt;\n&lt;p&gt;Odstavec textu.&lt;/p&gt;</code></pre><h2>Seznamy</h2><p>Neuspořádaný <code>&lt;ul&gt;</code>, uspořádaný <code>&lt;ol&gt;</code>, definiční <code>&lt;dl&gt;</code>.</p><pre><code>&lt;ul&gt;\n  &lt;li&gt;Položka 1&lt;/li&gt;\n  &lt;li&gt;Položka 2&lt;/li&gt;\n&lt;/ul&gt;\n&lt;ol&gt;\n  &lt;li&gt;Krok 1&lt;/li&gt;\n  &lt;li&gt;Krok 2&lt;/li&gt;\n&lt;/ol&gt;\n&lt;dl&gt;\n  &lt;dt&gt;HTML&lt;/dt&gt;\n  &lt;dd&gt;Jazyk pro strukturu webu&lt;/dd&gt;\n&lt;/dl&gt;</code></pre>', 'lesson', 3, 10, 10),

(@kurs_id, 'Odkazy a obrázky', '<h2>Odkazy</h2><p>Element <code>&lt;a&gt;</code> s atributem <code>href</code>. <code>target="_blank"</code> otevře v nové záložce, přidej <code>rel="noopener"</code> pro bezpečnost.</p><pre><code>&lt;a href="https://vevit.cz"&gt;VeVit&lt;/a&gt;\n&lt;a href="/kontakt" target="_blank" rel="noopener"&gt;Kontakt&lt;/a&gt;\n&lt;a href="#sekce"&gt;Skok na sekci&lt;/a&gt;</code></pre><h2>Obrázky</h2><p>Vždy uváděj <code>alt</code> pro přístupnost. <code>&lt;figure&gt;</code> s <code>&lt;figcaption&gt;</code> pro popisky.</p><pre><code>&lt;img src="logo.svg" alt="Logo VeVit" width="120" height="40"&gt;\n\n&lt;figure&gt;\n  &lt;img src="graf.png" alt="Graf vývoje"&gt;\n  &lt;figcaption&gt;Vývoj za rok 2025&lt;/figcaption&gt;\n&lt;/figure&gt;\n\n&lt;picture&gt;\n  &lt;source srcset="velky.webp" media="(min-width: 1024px)"&gt;\n  &lt;source srcset="maly.webp" media="(max-width: 640px)"&gt;\n  &lt;img src="stredni.jpg" alt="Responsivní obrázek"&gt;\n&lt;/picture&gt;</code></pre>', 'lesson', 4, 10, 12),

(@kurs_id, 'Formuláře a inputy', '<h2>Formuláře</h2><p>Element <code>&lt;form&gt;</code> obaluje celý formulář. Každý input musí mít <code>&lt;label&gt;</code> spojený přes <code>for</code>/<code>id</code>.</p><pre><code>&lt;form action="/odeslat" method="POST"&gt;\n  &lt;label for="jmeno"&gt;Jméno:&lt;/label&gt;\n  &lt;input type="text" id="jmeno" name="jmeno" required&gt;\n\n  &lt;label for="email"&gt;E-mail:&lt;/label&gt;\n  &lt;input type="email" id="email" name="email"&gt;\n\n  &lt;label for="heslo"&gt;Heslo:&lt;/label&gt;\n  &lt;input type="password" id="heslo" name="heslo"&gt;\n\n  &lt;input type="number" name="vek" min="1" max="120"&gt;\n  &lt;input type="date" name="datum"&gt;\n  &lt;input type="range" name="vol" min="0" max="100"&gt;\n  &lt;input type="color" name="barva" value="#7c3aed"&gt;\n\n  &lt;label&gt;&lt;input type="checkbox" name="souhlas"&gt; Souhlasím&lt;/label&gt;\n  &lt;label&gt;&lt;input type="radio" name="pohlavi" value="m"&gt; Muž&lt;/label&gt;\n  &lt;label&gt;&lt;input type="radio" name="pohlavi" value="z"&gt; Žena&lt;/label&gt;\n\n  &lt;label for="zeme"&gt;Země:&lt;/label&gt;\n  &lt;select id="zeme" name="zeme"&gt;\n    &lt;option value="cz"&gt;Česko&lt;/option&gt;\n    &lt;option value="sk"&gt;Slovensko&lt;/option&gt;\n  &lt;/select&gt;\n\n  &lt;textarea name="zprava" rows="4"&gt;&lt;/textarea&gt;\n\n  &lt;fieldset&gt;\n    &lt;legend&gt;Doručení&lt;/legend&gt;\n    &lt;label&gt;&lt;input type="radio" name="doruceni" value="posta"&gt; Pošta&lt;/label&gt;\n    &lt;label&gt;&lt;input type="radio" name="doruceni" value="kuryr"&gt; Kurýr&lt;/label&gt;\n  &lt;/fieldset&gt;\n\n  &lt;button type="submit"&gt;Odeslat&lt;/button&gt;\n&lt;/form&gt;</code></pre>', 'lesson', 5, 10, 15),

(@kurs_id, 'Tabulky', '<h2>Tabulky v HTML</h2><p>Struktura: <code>&lt;table&gt;</code>, <code>&lt;thead&gt;</code>, <code>&lt;tbody&gt;</code>, řádky <code>&lt;tr&gt;</code>, buňky hlavičky <code>&lt;th&gt;</code>, datové buňky <code>&lt;td&gt;</code>.</p><pre><code>&lt;table&gt;\n  &lt;caption&gt;Seznam studentů&lt;/caption&gt;\n  &lt;thead&gt;\n    &lt;tr&gt;\n      &lt;th scope="col"&gt;Jméno&lt;/th&gt;\n      &lt;th scope="col"&gt;Ročník&lt;/th&gt;\n      &lt;th scope="col"&gt;Průměr&lt;/th&gt;\n    &lt;/tr&gt;\n  &lt;/thead&gt;\n  &lt;tbody&gt;\n    &lt;tr&gt;\n      &lt;th scope="row"&gt;Karel&lt;/th&gt;\n      &lt;td&gt;3.&lt;/td&gt;\n      &lt;td&gt;1.8&lt;/td&gt;\n    &lt;/tr&gt;\n    &lt;tr&gt;\n      &lt;td colspan="2"&gt;Celkem 2 studenti&lt;/td&gt;\n      &lt;td rowspan="1"&gt;—&lt;/td&gt;\n    &lt;/tr&gt;\n  &lt;/tbody&gt;\n&lt;/table&gt;</code></pre><p><code>colspan</code> sloučí sloupce, <code>rowspan</code> sloučí řádky. <code>scope</code> pomáhá čtečkám obrazovky — <code>"col"</code> pro hlavičku sloupce, <code>"row"</code> pro hlavičku řádku. <code>&lt;caption&gt;</code> popisuje tabulku.</p>', 'lesson', 6, 10, 12),

(@kurs_id, 'Meta tagy a SEO', '<h2>Meta tagy pro SEO</h2><p>Meta tagy v <code>&lt;head&gt;</code> pomáhají vyhledávačům a sociálním sítím pochopit obsah stránky.</p><pre><code>&lt;meta name="description" content="VeVit — vzdělávací platforma"&gt;\n&lt;meta name="robots" content="index, follow"&gt;\n&lt;link rel="canonical" href="https://vevit.cz/lektor"&gt;\n\n&lt;!-- Open Graph --&gt;\n&lt;meta property="og:title" content="VeVit Lektor"&gt;\n&lt;meta property="og:description" content="Uč se programovat"&gt;\n&lt;meta property="og:image" content="https://vevit.cz/og.png"&gt;\n&lt;meta property="og:url" content="https://vevit.cz/lektor"&gt;\n\n&lt;!-- Twitter Card --&gt;\n&lt;meta name="twitter:card" content="summary_large_image"&gt;\n&lt;meta name="twitter:title" content="VeVit Lektor"&gt;\n&lt;meta name="twitter:image" content="https://vevit.cz/og.png"&gt;\n\n&lt;!-- Favicon --&gt;\n&lt;link rel="icon" type="image/svg+xml" href="/favicon.svg"&gt;\n&lt;link rel="apple-touch-icon" href="/apple-touch-icon.png"&gt;</code></pre><p><code>description</code> se zobrazuje ve výsledcích vyhledávání (max 160 znaků). <code>og:tags</code> ovlivňují náhled na Facebooku/LinkedInu. <code>canonical</code> zabraňuje duplicitám. <code>robots</code> řídí indexování.</p>', 'lesson', 7, 10, 12),

(@kurs_id, 'iframe, video a audio', '<h2>iframe</h2><p>Vložení cizí stránky. Vždy omez oprávnění atributem <code>sandbox</code>.</p><pre><code>&lt;iframe\n  src="https://maps.google.com/embed?pb=..."\n  width="600" height="400"\n  loading="lazy"\n  sandbox="allow-scripts allow-same-origin"\n  title="Mapa"&gt;\n&lt;/iframe&gt;</code></pre><h2>Video a audio</h2><p>Nativní HTML5 přehrávače s <code>controls</code>. Více formátů přes <code>&lt;source&gt;</code>. Skryté titulky přes <code>&lt;track&gt;</code>.</p><pre><code>&lt;video controls width="640" poster="nahled.jpg"&gt;\n  &lt;source src="video.webm" type="video/webm"&gt;\n  &lt;source src="video.mp4" type="video/mp4"&gt;\n  &lt;track kind="subtitles" src="titulky.vtt" srclang="cs" label="Česky"&gt;\n  Váš prohlížeč nepodporuje video.\n&lt;/video&gt;\n\n&lt;audio controls&gt;\n  &lt;source src="pisnicka.ogg" type="audio/ogg"&gt;\n  &lt;source src="pisnicka.mp3" type="audio/mpeg"&gt;\n&lt;/audio&gt;</code></pre>', 'lesson', 8, 10, 12),

(@kurs_id, 'Data atributy', '<h2>Data atributy</h2><p>Vlastní atributy <code>data-*</code> ukládají dodatečná data přímo v HTML. Přístup přes CSS selektory i JavaScript <code>dataset</code> API.</p><pre><code>&lt;div data-user-id="42" data-role="admin" data-theme="dark"&gt;\n  Karel, admin\n&lt;/div&gt;</code></pre><h2>Přístup v JavaScriptu</h2><pre><code>const el = document.querySelector("[data-user-id=\'42\']");\nconsole.log(el.dataset.userId);   // "42"\nconsole.log(el.dataset.role);     // "admin"\nel.dataset.theme = "light";       // změní data-theme</code></pre><h2>Selekce v CSS</h2><pre><code>[data-role="admin"] {\n  border: 2px solid #7c3aed;\n}\n[data-theme="dark"] {\n  background: #0f0f14;\n  color: #e2e8f0;\n}</code></pre><p>Pozor: <code>data-user-id</code> v HTML se stane <code>dataset.userId</code> v JS (camelCase).</p>', 'lesson', 9, 10, 10),

(@kurs_id, 'HTML5 API', '<h2>Dialog</h2><p>Nativní modální dialog bez JS frameworku. <code>showModal()</code> otevře s overlay, <code>close()</code> zavře.</p><pre><code>&lt;dialog id="modal"&gt;\n  &lt;h2&gt;Potvrzení&lt;/h2&gt;\n  &lt;p&gt;Opravdu chcete pokračovat?&lt;/p&gt;\n  &lt;button onclick="document.getElementById(\'modal\').close()"&gt;Zavřít&lt;/button&gt;\n&lt;/dialog&gt;\n&lt;button onclick="document.getElementById(\'modal\').showModal()"&gt;Otevřít&lt;/button&gt;</code></pre><h2>Details/Summary</h2><p>Skládací obsah bez JS.</p><pre><code>&lt;details&gt;\n  &lt;summary&gt;Časté otázky&lt;/summary&gt;\n  &lt;p&gt;Odpověď na otázku...&lt;/p&gt;\n&lt;/details&gt;\n&lt;details open&gt;\n  &lt;summary&gt;Veřejné info&lt;/summary&gt;\n  &lt;p&gt;Toto je ve výchozím stavu otevřeno.&lt;/p&gt;\n&lt;/details&gt;</code></pre><h2>Progress, Meter, Output</h2><pre><code>&lt;progress value="70" max="100"&gt;70 %&lt;/progress&gt;\n&lt;meter value="0.7" min="0" max="1" low="0.3" high="0.8"&gt;70 %&lt;/meter&gt;\n&lt;output for="a b" name="vysledek"&gt;42&lt;/output&gt;</code></pre>', 'lesson', 10, 10, 12);


-- ============================================================
-- KVÍZ 1: HTML základy (sort_order 11)
-- ============================================================

INSERT INTO lessons (course_id, title, content, lesson_type, sort_order, xp_reward, duration_minutes) VALUES
(@kurs_id, 'Kvíz 1 — HTML základy', '<p>Ověř znalosti HTML struktury, sémantických tagů, formulářů a tabulek.</p>', 'quiz', 11, 50, 12);

SET @q1 = LAST_INSERT_ID();

INSERT INTO quizzes (lesson_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, sort_order) VALUES
(@q1, 'K čemu slouží <!DOCTYPE html>?', 'Definuje barvu pozadí', 'Deklaruje typ dokumentu jako HTML5', 'Importuje CSS', 'Vytváří meta tag', 'b', '<!DOCTYPE html> říká prohlížeči, že dokument je HTML5 — zajišťuje standards mode.', 1),
(@q1, 'Který tag je sémantický pro hlavní navigaci?', '<nav>', '<div class="nav">', '<menu>', '<header>', 'a', '<nav> je sémantický tag určený pro navigační bloky — vyhledávače i čtečky obrazovky ho rozpoznají.', 2),
(@q1, 'Jaký je rozdíl mezi <ol> a <ul>?', '<ol> je odrážkový, <ul> číslovaný', '<ol> je číslovaný, <ul> je odrážkový', 'Žádný', '<ol> má 3 položky max', 'b', '<ol> (ordered list) tvoří číslovaný seznam, <ul> (unordered list) nečíslovaný s odrážkami.', 3),
(@q1, 'Co dělá atribut alt u <img>?', 'Nastavuje šířku', 'Zobrazuje text při nenaložení obrázku a čtečkám obrazovky', 'Přidává rámeček', 'Definuje formát', 'b', 'alt je alternativní text — zobrazí se při selhání načtení a čtou ho screen readery.', 4),
(@q1, 'Který atribut otevře odkaz v nové záložce?', 'rel="noopener"', 'target="_blank"', 'href="_new"', 'open="new"', 'b', 'target="_blank" otevře odkaz v nové záložce prohlížeče.', 5),
(@q1, 'K čemu slouží <fieldset> ve formuláři?', 'Skryje pole', 'Sdružuje související inputy s popiskem <legend>', 'Validuje data', 'Odesílá formulář', 'b', '<fieldset> vizuálně a sémanticky seskupuje související formulářová pole, <legend> je jejich popisek.', 6),
(@q1, 'Co znamená colspan v tabulce?', 'Sloučí řádky', 'Sloučí sloupce buňky', 'Přidá sloupec', 'Smaže buňku', 'b', 'colspan určuje, kolik sloupců daná buňka zabírá (sloučení sloupců).', 7),
(@q1, 'Jaký meta tag zajistí správné škálování na mobilu?', 'meta charset', 'meta viewport s width=device-width', 'meta refresh', 'meta author', 'b', '<meta name="viewport" content="width=device-width, initial-scale=1.0"> zajistí, že se stránka správně přizpůsobí mobilnímu displeji.', 8);


-- ============================================================
-- SEKCE 2: CSS základy (sort_order 12-25)
-- ============================================================

INSERT INTO lessons (course_id, title, content, lesson_type, sort_order, xp_reward, duration_minutes) VALUES
(@kurs_id, 'Selektory a specifičnost', '<h2>Typy selektorů</h2><p>Typový: <code>p</code>, třídový: <code>.nazev</code>, ID: <code>#unikat</code>, atributový: <code>[type="email"]</code>. Kombinátory: potomek <code> </code>, dítě <code>&gt;</code>, sourozenec <code>+</code>, obecný sourozenec <code>~</code>.</p><pre><code>/* Typový */\np { color: #e2e8f0; }\n/* Třídový */\n.karta { background: #1a1a24; }\n/* ID */\n#logo { width: 120px; }\n/* Atributový */\ninput[type="email"] { border-color: #7c3aed; }\n/* Potomek */\n.karta h2 { font-size: 1.5rem; }\n/* Dítě */\n.nav &gt; li { display: inline-block; }</code></pre><h2>Specifičnost</h2><p>Počítá se: ID (100) &gt; třída/atribut/pseudo-třída (10) &gt; element/pseudo-element (1). <code>!important</code> přepíše vše, ale vyhni se mu.</p><pre><code>/* Specifičnost: 0-1-1 */\ndiv.karta { color: white; }\n/* Specifičnost: 1-0-0 — vyhraje */\n#karta { color: purple; }\n/* !important přepíše vše */\np { color: red !important; }</code></pre>', 'lesson', 12, 15, 12),

(@kurs_id, 'Box model', '<h2>Box model</h2><p>Každý element je obdélník: obsah (content) + vnitřní okraj (padding) + rámeček (border) + vnější okraj (margin).</p><pre><code>.karta {\n  width: 300px;\n  padding: 16px;       /* vnitřní okraj */\n  border: 1px solid #7c3aed; /* rámeček */\n  margin: 24px;        /* vnější okraj */\n  box-sizing: border-box; /* šířka zahrnuje padding+border */\n}</code></pre><p>Bez <code>box-sizing: border-box</code> se <code>width</code> vztahuje jen na content — padding a border se přičítají. S <code>border-box</code> je <code>width</code> celková šířka včetně padding a border. Doporučeno globálně:</p><pre><code>*, *::before, *::after {\n  box-sizing: border-box;\n}</code></pre><p><code>outline</code> se kreslí mimo box model, nezabírá místo — ideální pro focus indikátory.</p>', 'lesson', 13, 15, 12),

(@kurs_id, 'Flexbox (kompletní)', '<h2>Flexbox — display: flex</h2><p>Jednorozměrné rozložení (řádek nebo sloupec). Rodič dostane <code>display: flex</code>, děti se automaticky uspořádají.</p><pre><code>.flex-kontejner {\n  display: flex;\n  justify-content: space-between; /* hlavní osa */\n  align-items: center;            /* příčná osa */\n  flex-wrap: wrap;                /* zalamování */\n  gap: 16px;                     /* mezery mezi položkami */\n  flex-direction: row;           /* směr */\n}</code></pre><h2>Flex položky</h2><pre><code>.flex-polozka {\n  flex-grow: 1;    /* jak moc se roztáhne */\n  flex-shrink: 0;  /* jak moc se smrští */\n  flex-basis: 200px; /* výchozí velikost */\n  /* Zkratka: */\n  flex: 1 0 200px;\n  order: -1;       /* pořadí položky */\n  align-self: flex-end; /* vlastní zarovnání */\n}</code></pre><p>Tip: <code>gap</code> nahrazuje margin hacky — funguje i v Gridu.</p>', 'lesson', 14, 15, 15),

(@kurs_id, 'CSS Grid (kompletní)', '<h2>CSS Grid — dvourozměrné rozložení</h2><p>Grid umožňuje rozložení do řádků i sloupců najednou. Ideální pro layout celé stránky.</p><pre><code>.grid-kontejner {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  grid-template-rows: auto 1fr auto;\n  gap: 24px;\n  /* Minmax pro responzivní karty */\n  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));\n}\n\n/* Pojmenované oblasti */\n.layout {\n  display: grid;\n  grid-template-areas:\n    "nav nav nav"\n    "sidebar main main"\n    "footer footer footer";\n  grid-template-columns: 250px 1fr 1fr;\n}\n.nav    { grid-area: nav; }\n.sidebar { grid-area: sidebar; }\n.main   { grid-area: main; }\n.footer { grid-area: footer; }</code></pre><p><code>fr</code> = zlomek dostupného prostoru. <code>auto-fill</code> vs <code>auto-fit</code>: fill vytvoří prázdné stopy, fit sbalí přebytečné. <code>minmax()</code> definuje rozsah šířky sloupce.</p>', 'lesson', 15, 15, 15),

(@kurs_id, 'Media queries (mobile-first)', '<h2>Media queries</h2><p>Responzivní styly pomocí <code>@media</code>. Mobile-first = základní styly pro mobil, přepisuješ pro větší obrazovky.</p><pre><code>/* Mobile-first — základní styly */\n.karta {\n  flex-direction: column;\n  padding: 12px;\n}\n\n/* 640px+ (sm) */\n@media (min-width: 640px) {\n  .karta { flex-direction: row; }\n}\n\n/* 768px+ (md) */\n@media (min-width: 768px) {\n  .karta { padding: 24px; }\n}\n\n/* 1024px+ (lg) */\n@media (min-width: 1024px) {\n  .sidebar { width: 300px; }\n}\n\n/* 1280px+ (xl) */\n@media (min-width: 1280px) {\n  .container { max-width: 1200px; margin: 0 auto; }\n}</code></pre><p>Breakpointy odpovídají Tailwind CSS: sm=640, md=768, lg=1024, xl=1280. Mobile-first píše méně kódu a lépe funguje.</p>', 'lesson', 16, 15, 12),

(@kurs_id, 'Tailwind CSS via CDN', '<h2>Tailwind CSS — utility-first</h2><p>Tailwind poskytuje třídy jako <code>flex</code>, <code>p-4</code>, <code>text-xl</code> místo psaní vlastního CSS. Přes CDN jej přidáš jedním řádkem.</p><pre><code>&lt;!DOCTYPE html&gt;\n&lt;html lang="cs"&gt;\n&lt;head&gt;\n  &lt;meta charset="UTF-8"&gt;\n  &lt;meta name="viewport" content="width=device-width, initial-scale=1.0"&gt;\n  &lt;script src="https://cdn.tailwindcss.com"&gt;&lt;/script&gt;\n  &lt;title&gt;VeVit — Tailwind&lt;/title&gt;\n&lt;/head&gt;\n&lt;body class="bg-[#0f0f14] text-white"&gt;\n  &lt;div class="flex items-center justify-between p-6 bg-[#1a1a24] rounded-xl"&gt;\n    &lt;h1 class="text-2xl font-bold"&gt;VeVit&lt;/h1&gt;\n    &lt;button class="bg-[#7c3aed] hover:bg-purple-600 px-4 py-2 rounded-lg"&gt;\n      Přihlásit\n    &lt;/button&gt;\n  &lt;/div&gt;\n&lt;/body&gt;\n&lt;/html&gt;</code></pre><h2>Responsive prefix a dark:</h2><pre><code>&lt;!-- md: platí od 768px+ --&gt;\n&lt;div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4"&gt;\n  &lt;div class="p-4 dark:bg-[#1a1a24]"&gt;Karta&lt;/div&gt;\n&lt;/div&gt;\n\n&lt;!-- @apply pro opakující se styly --&gt;\n&lt;style type="text/tailwindcss"&gt;\n  .btn-primary {\n    @apply bg-[#7c3aed] text-white px-6 py-2 rounded-lg hover:bg-purple-600 transition;\n  }\n&lt;/style&gt;</code></pre>', 'lesson', 17, 15, 15),

(@kurs_id, 'CSS proměnné', '<h2>Custom properties</h2><p>CSS proměnné začínají <code>--</code>, čtou se funkcí <code>var()</code>. Definují se v <code>:root</code> pro globální platnost. Umožňují témata a snadné změny.</p><pre><code>:root {\n  --bg-primary: #0f0f14;\n  --bg-surface: #1a1a24;\n  --accent: #7c3aed;\n  --text: #e2e8f0;\n  --text-muted: #94a3b8;\n  --radius: 12px;\n}\n\n.karta {\n  background: var(--bg-surface);\n  color: var(--text);\n  border-radius: var(--radius);\n  border: 1px solid var(--accent);\n}\n\n/* Fallback hodnota */\np {\n  color: var(--neexistuje, #94a3b8);\n}</code></pre><h2>Témata přes proměnné</h2><pre><code>[data-theme="light"] {\n  --bg-primary: #ffffff;\n  --bg-surface: #f1f5f9;\n  --text: #1e293b;\n  --text-muted: #64748b;\n}</code></pre>', 'lesson', 18, 15, 12),

(@kurs_id, 'Animace a transitions', '<h2>Transitions</h2><p>Plynulý přechod mezi stavy. Definuje se na elementu, aktivuje se změnou hodnoty (např. hover).</p><pre><code>.tlacitko {\n  background: #7c3aed;\n  transition: background 0.3s ease, transform 0.2s ease;\n}\n.tlacitko:hover {\n  background: #6d28d9;\n  transform: scale(1.05);\n}</code></pre><h2>@keyframes animace</h2><p>Komplexnější animace s více kroky.</p><pre><code>@keyframes fadeIn {\n  from { opacity: 0; transform: translateY(20px); }\n  to   { opacity: 1; transform: translateY(0); }\n}\n\n.karta {\n  animation: fadeIn 0.6s ease-out forwards;\n  transform-origin: center bottom;\n}\n\n/* Více kroků */\n@keyframes pulse {\n  0%, 100% { box-shadow: 0 0 0 0 rgba(124,58,237,0.4); }\n  50%       { box-shadow: 0 0 0 12px rgba(124,58,237,0); }\n}\n.badge { animation: pulse 2s infinite; }\n\n/* Optimalizace */\n.animovany {\n  will-change: transform, opacity;\n}</code></pre>', 'lesson', 19, 15, 13),

(@kurs_id, 'Transforms (2D + 3D)', '<h2>2D transformace</h2><p><code>translate()</code> posun, <code>rotate()</code> rotace, <code>scale()</code> měřítko, <code>skew()</code> zkosení.</p><pre><code>.karta {\n  transform: translateX(20px) rotate(3deg) scale(1.05);\n  transition: transform 0.3s ease;\n}\n.karta:hover {\n  transform: translateX(0) rotate(0) scale(1);\n}</code></pre><h2>3D transformace</h2><pre><code>.scena {\n  perspective: 1000px; /* vzdálenost diváka */\n}\n\n.kostka {\n  transform-style: preserve-3d;\n  transform: rotateY(45deg) rotateX(20deg);\n}\n\n.predni-strana {\n  transform: translateZ(50px);\n  backface-visibility: hidden;\n}\n\n/* Flip karta */\n.flip-karta {\n  perspective: 800px;\n}\n.flip-inner {\n  transform-style: preserve-3d;\n  transition: transform 0.6s;\n}\n.flip-karta:hover .flip-inner {\n  transform: rotateY(180deg);\n}\n.flip-zadni {\n  transform: rotateY(180deg);\n  backface-visibility: hidden;\n}</code></pre>', 'lesson', 20, 15, 13),

(@kurs_id, 'Pseudo-třídy a pseudo-elementy', '<h2>Pseudo-třídy</h2><p>Stavy elementu: <code>:hover</code>, <code>:focus</code>, <code>:active</code>, <code>:focus-visible</code>, <code>:first-child</code>, <code>:last-child</code>, <code>:nth-child()</code>, <code>:not()</code>, <code>:is()</code>, <code>:where()</code>.</p><pre><code>li:nth-child(odd) { background: #1a1a24; }\nli:nth-child(3n+1) { color: #7c3aed; }\ninput:not(:disabled) { border-color: #7c3aed; }\n:is(h1, h2, h3):hover { color: #7c3aed; }\ninput:focus-visible {\n  outline: 2px solid #7c3aed;\n  outline-offset: 2px;\n}</code></pre><h2>Pseudo-elementy</h2><pre><code>.karta::before {\n  content: "";\n  position: absolute;\n  inset: 0;\n  background: linear-gradient(135deg, #7c3aed22, transparent);\n  border-radius: inherit;\n  pointer-events: none;\n}\n.odkaz::after {\n  content: " →";\n}\ninput::placeholder {\n  color: #64748b;\n  opacity: 1;\n}</code></pre>', 'lesson', 21, 15, 12),

(@kurs_id, 'Formuláře styling', '<h2>Stylování formulářů</h2><p>Inputy v dark theme vyžadují explicitní styly — výchozí vzhled prohlížeče nezapadá do tmavého designu.</p><pre><code>input, select, textarea {\n  background: #1a1a24;\n  color: #e2e8f0;\n  border: 1px solid #334155;\n  border-radius: 8px;\n  padding: 10px 14px;\n  font-size: 1rem;\n  transition: border-color 0.2s, box-shadow 0.2s;\n}\n\ninput:focus-visible {\n  border-color: #7c3aed;\n  box-shadow: 0 0 0 3px rgba(124, 58, 237, 0.25);\n  outline: none;\n}\n\ninput:valid { border-color: #22c55e; }\ninput:invalid:not(:placeholder-shown) { border-color: #ef4444; }\n\n/* Vypnutí výchozího vzhledu */\nselect { appearance: none; }\ninput[type="checkbox"] { appearance: none; width: 20px; height: 20px; }\ninput[type="checkbox"]:checked {\n  background: #7c3aed;\n  background-image: url("data:image/svg+xml,...");\n}\ninput[type="radio"] {\n  appearance: none;\n  width: 20px; height: 20px;\n  border-radius: 50%;\n  border: 2px solid #7c3aed;\n}\ninput[type="radio"]:checked {\n  background: #7c3aed;\n  box-shadow: inset 0 0 0 3px #0f0f14;\n}</code></pre>', 'lesson', 22, 15, 13),

(@kurs_id, 'Neomorfní design (VeVit styl)', '<h2>Neomorfní dark theme</h2><p>VeVit styl kombinuje tmavé pozadí s měkkými stíny a fialovým akcentem. Výsledkem je moderní „vyvýšený" vzhled prvků.</p><pre><code>/* Základní paleta */\n:root {\n  --bg-primary: #0f0f14;\n  --bg-surface: #1a1a24;\n  --accent: #7c3aed;\n  --text: #e2e8f0;\n  --shadow-dark: #0a0a0f;\n  --shadow-light: #252530;\n}\n\n/* Vydutý prvek */\n.karta-neomorf {\n  background: #1a1a24;\n  border-radius: 16px;\n  box-shadow:\n    6px 6px 12px #0a0a0f,\n    -6px -6px 12px #252530;\n  padding: 24px;\n  border: 1px solid rgba(124, 58, 237, 0.1);\n}\n\n/* Zapadlý prvek */\n.input-neomorf {\n  background: #15151e;\n  border-radius: 12px;\n  box-shadow:\n    inset 4px 4px 8px #0a0a0f,\n    inset -4px -4px 8px #252530;\n  padding: 12px 16px;\n  border: none;\n}\n\n/* Glow efekt na hover */\n.karta-neomorf:hover {\n  border-color: rgba(124, 58, 237, 0.3);\n  box-shadow:\n    6px 6px 12px #0a0a0f,\n    -6px -6px 12px #252530,\n    0 0 20px rgba(124, 58, 237, 0.15);\n}</code></pre>', 'lesson', 23, 15, 13),

(@kurs_id, 'Typografie (Sora font)', '<h2>Google Fonts — Sora</h2><p>Sora je moderní geometrické písmo, ideální pro tech/UI projekty. Načti z Google Fonts a nastav jako výchozí.</p><pre><code>&lt;link rel="preconnect" href="https://fonts.googleapis.com"&gt;\n&lt;link href="https://fonts.googleapis.com/css2?family=Sora:wght@300;400;500;600;700&amp;display=swap" rel="stylesheet"&gt;</code></pre><pre><code>body {\n  font-family: "Sora", sans-serif;\n  font-weight: 400;\n  font-size: 16px;\n  line-height: 1.6;\n  color: #e2e8f0;\n  -webkit-font-smoothing: antialiased;\n}\n\nh1, h2, h3 {\n  font-weight: 700;\n  line-height: 1.2;\n  letter-spacing: -0.02em;\n}\nh1 { font-size: 2.5rem; }\nh2 { font-size: 1.75rem; }\nh3 { font-size: 1.25rem; }\n\n/* Vertikální rytmus */\np, ul, ol { margin-bottom: 1.5rem; }\nh2 { margin-top: 2rem; margin-bottom: 1rem; }\n\n/* Textový stín pro nadpisy v dark mode */\nh1, h2 {\n  text-shadow: 0 0 30px rgba(124, 58, 237, 0.3);\n}</code></pre>', 'lesson', 24, 15, 12),

(@kurs_id, 'Barvy a gradienty', '<h2>Formáty barev</h2><p><code>hex</code> (#7c3aed), <code>rgb</code> (rgb(124,58,237)), <code>hsl</code> (hsl(263,80%,58%)), <code>currentColor</code> zdědí barvu textu rodiče.</p><pre><code>.akcent { color: #7c3aed; }\n.polopruhledna { background: rgba(124, 58, 237, 0.5); }\n.s-hsl { color: hsl(263, 80%, 58%); }\n.zdedena { border-color: currentColor; }</code></pre><h2>Gradienty</h2><pre><code>/* Lineární */\n.hero {\n  background: linear-gradient(135deg, #0f0f14 0%, #1a1a24 100%);\n}\n/* S akcentem */\n.gradient-fialovy {\n  background: linear-gradient(135deg, #7c3aed, #a855f7);\n}\n\n/* Radiální */\n.spotlight {\n  background: radial-gradient(circle at top, #7c3aed33, #0f0f14 70%);\n}\n\n/* Conic */\n.kolovec {\n  background: conic-gradient(#7c3aed 0deg, #a855f7 120deg, #0f0f14 120deg 360deg);\n  border-radius: 50%;\n}\n\n/* Opacity */\n.prekryv { background: rgba(15, 15, 20, 0.85); backdrop-filter: blur(8px); }</code></pre>', 'lesson', 25, 15, 12);


-- ============================================================
-- KVÍZ 2: CSS základy (sort_order 26)
-- ============================================================

INSERT INTO lessons (course_id, title, content, lesson_type, sort_order, xp_reward, duration_minutes) VALUES
(@kurs_id, 'Kvíz 2 — CSS základy', '<p>Ověř znalosti selektorů, box modelu, Flexboxu, Gridu a Tailwindu.</p>', 'quiz', 26, 50, 12);

SET @q2 = LAST_INSERT_ID();

INSERT INTO quizzes (lesson_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, sort_order) VALUES
(@q2, 'Který selektor má nejvyšší specifičnost?', '.karta h2', '#nadpis', 'div > p', 'body main section', 'b', 'ID selektor (#nadpis) má specifičnost 1-0-0, což převažuje jakoukoliv kombinaci tříd a elementů.', 1),
(@q2, 'Co dělá box-sizing: border-box?', 'Přidá rámeček', 'Šířka zahrnuje padding a border', 'Odstraní margin', 'Zvětší content', 'b', 'S border-box je width celková šířka včetně padding a border — padding se nepřičítá navíc.', 2),
(@q2, 'Jak zarovnáš položky na příčné ose ve Flexboxu?', 'justify-content', 'align-items', 'flex-wrap', 'gap', 'b', 'align-items zarovnává flex položky na příčné ose (cross axis). justify-content pracuje na hlavní ose.', 3),
(@q2, 'Co znamená 1fr v CSS Grid?', '1 pixel', '1 zlomek dostupného prostoru', '1. sloupec', 'První řádek', 'b', 'fr (fraction) je jednotka reprezentující podíl dostupného prostoru — 1fr = jeden díl z celku.', 4),
(@q2, 'Co je mobile-first v media queries?', 'max-width dotazy', 'min-width dotazy od nejnižšího breakpointu', 'Žádné dotazy', 'Pouze desktop', 'b', 'Mobile-first píše základní styly pro mobil a přepisuje pomocí @media (min-width: ...) pro větší obrazovky.', 5),
(@q2, 'Jak přidáš Tailwind CSS přes CDN?', '<link href="tailwind.css">', '<script src="https://cdn.tailwindcss.com">', '<style>@import tailwindcss</style>', 'npm install tailwindcss', 'b', 'Tailwind CDN se přidává přes <script src="https://cdn.tailwindcss.com"> tag v hlavičce.', 6),
(@q2, 'K čemu slouží CSS proměnná --accent?', 'Je vestavěná v CSS', 'Uživatelsky definovaná hodnota pro opakovanou barvu/hodnotu', 'Je to chybová zpráva', 'Je to komentář', 'b', '--accent je custom property — uživatelsky definovaná proměnná čitelná přes var(--accent).', 7),
(@q2, 'Co dělá transition v CSS?', 'Spustí animaci', 'Plynule přechází mezi stavy elementu', 'Zastaví animaci', 'Mění barvu', 'b', 'transition definuje plynulý přechod (duration, timing) při změně CSS vlastnosti, např. hover efekt.', 8);


-- ============================================================
-- SEKCE 3: Pokročilé CSS + HTML (sort_order 27-39)
-- ============================================================

INSERT INTO lessons (course_id, title, content, lesson_type, sort_order, xp_reward, duration_minutes) VALUES
(@kurs_id, 'CSS filtry + backdrop-filter', '<h2>CSS filtry</h2><p>Filtry upravují vizuální vzhled elementu: <code>blur()</code>, <code>brightness()</code>, <code>contrast()</code>, <code>saturate()</code>, <code>grayscale()</code>, <code>hue-rotate()</code>.</p><pre><code>.obrazek:hover {\n  filter: brightness(1.1) saturate(1.2);\n}\n.ztlumena {\n  filter: blur(4px) grayscale(0.5);\n}\n/* Více filtrů naráz */\n.kombinovane {\n  filter: contrast(1.1) brightness(0.95) saturate(1.1);\n}</code></pre><h2>Backdrop-filter — glassmorphism</h2><p><code>backdrop-filter</code> aplikuje filtr na obsah ZA elementem. Ideální pro glassmorphism efekt.</p><pre><code>.sklo {\n  background: rgba(26, 26, 36, 0.6);\n  backdrop-filter: blur(12px) saturate(1.8);\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  border-radius: 16px;\n  padding: 24px;\n}\n\n/* Glassmorphism karta v dark theme */\n.glass-karta {\n  background: rgba(26, 26, 36, 0.4);\n  backdrop-filter: blur(16px);\n  border: 1px solid rgba(124, 58, 237, 0.15);\n  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);\n}</code></pre>', 'lesson', 27, 20, 13),

(@kurs_id, 'Scroll snapping', '<h2>Scroll snapping</h2><p>Umožňuje přichytit scroll k definovaným bodům — ideální pro galerie, carousel, fullscreen sekce.</p><pre><code>/* Kontejner */\n.snap-kontejner {\n  scroll-snap-type: x mandatory;  /* horizontální snap */\n  overflow-x: auto;\n  display: flex;\n  gap: 16px;\n}\n\n/* Položky */\n.snap-polozka {\n  scroll-snap-align: start;  /* start | center | end */\n  flex: 0 0 300px;\n}\n\n/* Vertikální fullscreen snap */\n.snap-stranky {\n  scroll-snap-type: y proximity;  /* proximity = jemnější */\n  height: 100vh;\n  overflow-y: auto;\n}\n.snap-sekce {\n  scroll-snap-align: start;\n  min-height: 100vh;\n}</code></pre><p><code>mandatory</code> vždy přichytí, <code>proximity</code> jen když je blízko. <code>scroll-snap-stop: always</code> zakáže přeskočení snap bodu.</p>', 'lesson', 28, 20, 12),

(@kurs_id, 'Container queries', '<h2>Container queries</h2><p>Styluješ komponentu podle velikosti jejího rodiče, ne podle viewportu. Klíčové pro znovupoužitelné komponenty.</p><pre><code>/* Rodič musí deklarovat container */\n.sidebar {\n  container-type: inline-size;\n  container-name: sidebar;\n}\n\n/* Styly podle šířky kontejneru */\n@container sidebar (min-width: 400px) {\n  .karta-uvnitr {\n    flex-direction: row;\n  }\n}\n\n@container sidebar (min-width: 600px) {\n  .karta-uvnitr {\n    grid-template-columns: 1fr 1fr;\n  }\n}\n\n/* Zkrácený zápis */\n.widget {\n  container: widget / inline-size;\n}</code></pre><p>Rozdíl od media queries: komponenta reaguje na prostor, který má k dispozici, ne na šířku okna. Lze ji vložit kamkoliv.</p>', 'lesson', 29, 20, 13),

(@kurs_id, 'Logical properties', '<h2>Logické vlastnosti</h2><p>Logické vlastnosti nahrazují fyzické (top/right/bottom/left) směrově nezávislými ekvivalenty. Podporují různé režimy zápisu (writing-mode).</p><pre><code>/* Fyzické vs logické */\nmargin-top    → margin-block-start\nmargin-bottom → margin-block-end\nmargin-left   → margin-inline-start\nmargin-right  → margin-inline-end\n\n/* Zkratky */\nmargin-block: 16px;        /* top + bottom */\nmargin-inline: auto;        /* left + right */\npadding-block: 12px 24px;    /* start end */\n\n/* Inset (top/right/bottom/left) */\ninset: 0;                   /* všude 0 */\ninset-block-start: 10px;\ninset-inline-start: 0;\n\n/* Border */\nborder-inline: 2px solid #7c3aed;\nborder-block-end: 1px solid #334155;\n\n/* Různý writing-mode */\n[dir="rtl"] .odkaz {\n  margin-inline-start: 8px;\n}</code></pre>', 'lesson', 30, 20, 12),

(@kurs_id, 'SVG inline', '<h2>Inline SVG</h2><p>SVG přímo v HTML — žádný HTTP request, plná kontrola přes CSS i JS.</p><pre><code>&lt;svg viewBox="0 0 24 24" width="24" height="24" fill="none"\n     stroke="#7c3aed" stroke-width="2"&gt;\n  &lt;path d="M12 2L2 7l10 5 10-5-10-5z"/&gt;\n  &lt;path d="M2 17l10 5 10-5"/&gt;\n  &lt;path d="M2 12l10 5 10-5"/&gt;\n&lt;/svg&gt;\n\n&lt;!-- Základní tvary --&gt;\n&lt;svg viewBox="0 0 200 100" width="200" height="100"&gt;\n  &lt;rect x="10" y="10" width="80" height="80" rx="8"\n        fill="#1a1a24" stroke="#7c3aed"/&gt;\n  &lt;circle cx="150" cy="50" r="40"\n          fill="#7c3aed" opacity="0.8"/&gt;\n&lt;/svg&gt;</code></pre><h2>SVG animace</h2><pre><code>&lt;svg viewBox="0 0 100 100" width="100" height="100"&gt;\n  &lt;circle cx="50" cy="50" r="40" fill="#7c3aed"&gt;\n    &lt;animate attributeName="r" from="40" to="45"\n             dur="1s" repeatCount="indefinite"\n             values="40;45;40" keyTimes="0;0.5;1"/&gt;\n  &lt;/circle&gt;\n&lt;/svg&gt;</code></pre>', 'lesson', 31, 20, 13),

(@kurs_id, 'Canvas základy', '<h2>Canvas API</h2><p>Element <code>&lt;canvas&gt;</code> poskytuje plochu pro kreslení 2D grafiky pomocí JavaScriptu.</p><pre><code>&lt;canvas id="mojePlatno" width="400" height="300"&gt;&lt;/canvas&gt;</code></pre><pre><code>const canvas = document.getElementById("mojePlatno");\nconst ctx = canvas.getContext("2d");\n\n// Obdélník\nctx.fillStyle = "#7c3aed";\nctx.fillRect(20, 20, 150, 100);\n\n// Obrys\nctx.strokeStyle = "#1a1a24";\nctx.lineWidth = 3;\nctx.strokeRect(25, 25, 140, 90);\n\n// Kruh\nctx.beginPath();\nctx.arc(300, 150, 60, 0, Math.PI * 2);\nctx.fillStyle = "#7c3aed";\nctx.fill();\n\n// Text\nctx.font = "24px Sora, sans-serif";\nctx.fillStyle = "#e2e8f0";\nctx.fillText("VeVit", 50, 250);\n\n// Obrázek\nconst img = new Image();\nimg.src = "logo.png";\nimg.onload = () =&gt; {\n  ctx.drawImage(img, 0, 0, 100, 100);\n};</code></pre>', 'lesson', 32, 20, 15),

(@kurs_id, 'Přístupnost (ARIA + focus)', '<h2>ARIA atributy</h2><p>ARIA doplňuje sémantiku tam, kde HTML tagy nestačí. Pravidlo: nepoužívej ARIA, pokud existuje nativní HTML element.</p><pre><code>&lt;!-- role --&gt;\n&lt;div role="navigation" aria-label="Hlavní menu"&gt;...&lt;/div&gt;\n\n&lt;!-- aria-label --&gt;\n&lt;button aria-label="Zavřít"&gt;✕&lt;/button&gt;\n\n&lt;!-- aria-describedby --&gt;\n&lt;input id="heslo" aria-describedby="napoveda"&gt;\n&lt;span id="napoveda"&gt;Min. 8 znaků&lt;/span&gt;\n\n&lt;!-- aria-expanded --&gt;\n&lt;button aria-expanded="false" aria-controls="panel"&gt;Více&lt;/button&gt;\n&lt;div id="panel" hidden&gt;Detaily...&lt;/div&gt;\n\n&lt;!-- tabindex --&gt;\n&lt;div tabindex="0"&gt;Focusovatelný blok&lt;/div&gt;\n\n&lt;!-- Skip link --&gt;\n&lt;a href="#main" class="sr-only focus:not-sr-only"&gt;\n  Přeskočit na obsah\n&lt;/a&gt;</code></pre><p><code>tabindex="-1"</code> = programově focus, ale ne v Tab. <code>tabindex="0"</code> = v Tab pořadí. Nikdy <code>tabindex</code> větší než 0.</p>', 'lesson', 33, 20, 14),

(@kurs_id, 'Core Web Vitals + optimalizace', '<h2>Core Web Vitals</h2><p>Tři klíčové metriky od Googlu: <strong>LCP</strong> (Largest Contentful Paint — max 2.5s), <strong>FID</strong> (First Input Delay — max 100ms), <strong>CLS</strong> (Cumulative Layout Shift — max 0.1).</p><pre><code>&lt;!-- LCP: preload kritických obrázků --&gt;\n&lt;link rel="preload" as="image" href="hero.webp"&gt;\n\n&lt;!-- LCP: font-display swap --&gt;\n&lt;link href="https://fonts.googleapis.com/css2?family=Sora&amp;display=swap" rel="stylesheet"&gt;\n\n&lt;!-- CLS: vždy uváděj rozměry obrázku --&gt;\n&lt;img src="karta.webp" width="400" height="300" alt="Karta"&gt;\n\n&lt;!-- CLS: rezerva pro reklamy/dynamický obsah --&gt;\n&lt;div style="min-height: 250px;"&gt;Reklama&lt;/div&gt;\n\n&lt;!-- Lazy loading --&gt;\n&lt;img src="dalsi.webp" loading="lazy" alt="Další obrázek"&gt;\n\n&lt;!-- Preload kritického CSS --&gt;\n&lt;link rel="preload" as="style" href="kriticke.css"&gt;\n\n&lt;!-- Preconnect pro externí zdroje --&gt;\n&lt;link rel="preconnect" href="https://fonts.gstatic.com"&gt;</code></pre>', 'lesson', 34, 20, 14),

(@kurs_id, 'Tmavý a světlý motiv', '<h2>prefers-color-scheme</h2><p>Automatická detekce preferencí uživatele systémem.</p><pre><code>:root {\n  --bg-primary: #0f0f14;\n  --bg-surface: #1a1a24;\n  --text: #e2e8f0;\n}\n\n@media (prefers-color-scheme: light) {\n  :root {\n    --bg-primary: #ffffff;\n    --bg-surface: #f1f5f9;\n    --text: #1e293b;\n  }\n}</code></pre><h2>Manuální přepínání + localStorage</h2><pre><code>/* Třída na html elementu */\nhtml.dark {\n  --bg-primary: #0f0f14;\n  --bg-surface: #1a1a24;\n}\nhtml.light {\n  --bg-primary: #ffffff;\n  --bg-surface: #f1f5f9;\n}</code></pre><pre><code>// JS: přepínání motivu\nconst toggle = document.getElementById("theme-toggle");\nconst html = document.documentElement;\n\nfunction setTheme(theme) {\n  html.className = theme;\n  localStorage.setItem("theme", theme);\n}\n\n// Načti uložený motiv\nconst saved = localStorage.getItem("theme")\n  || (matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light");\nsetTheme(saved);\n\ntoggle.addEventListener("click", () =&gt; {\n  setTheme(html.className === "dark" ? "light" : "dark");\n});</code></pre><p>Tip: Tailwind <code>dark:</code> prefix automaticky reaguje na <code>class="dark"</code> na html elementu.</p>', 'lesson', 35, 20, 14),

(@kurs_id, 'Print CSS', '<h2>@media print</h2><p>Styly pro tisk skryjí nepotřebné prvky a upraví barvy/rozložení pro papír.</p><pre><code>@media print {\n  /* Skrýt navigaci, footery, reklamy */\n  nav, footer, .sidebar, .ads { display: none; }\n\n  /* Černý text na bílém pozadí */\n  body {\n    background: white;\n    color: black;\n    font-size: 12pt;\n  }\n\n  /* Zobrazit URL odkazů */\n  a[href]::after {\n    content: " (" attr(href) ")";\n    font-size: 0.8em;\n    color: #555;\n  }\n\n  /* Zalomení stránek */\n  h2 { page-break-before: always; }\n  .karta { page-break-inside: avoid; }\n\n  /* Sirotci a vdovy */\n  p {\n    orphans: 3;  /* min řádků na konci stránky */\n    widows: 3;   /* min řádků na začátku stránky */\n  }\n\n  /* Skrýt obrázky pozadí */\n  * { background-image: none !important; }\n}</code></pre>', 'lesson', 36, 20, 12),

(@kurs_id, 'CSS subgrid', '<h2>Subgrid</h2><p>Pod-grid umožňuje vnořeným gridům sdílet stopy rodiče — zajišťuje dokonalé zarovnání napříč kartami.</p><pre><code>/* Rodičovský grid */\n.grid-seznam {\n  display: grid;\n  grid-template-columns: 1fr 2fr 1fr;\n  gap: 16px;\n}\n\n/* Karta sdílí sloupce rodiče */\n.karta {\n  display: grid;\n  grid-row: span 3; /* karta zabírá 3 řádky */\n  grid-template-columns: subgrid;\n  grid-template-rows: subgrid;\n}\n\n/* Prvky karty se zarovnají s okolními kartami */\n.karta-nadpis { grid-column: 1 / -1; }\n.karta-obsah  { grid-column: 2; }\n.karta-akce   { grid-column: 1 / -1; }</code></pre><p>Bez subgridu by každá karta měla vlastní nezávislý grid — nadpisy a obsahy by nebyly zarovnány. Subgrid řeší tento problém elegantně.</p>', 'lesson', 37, 20, 12),

(@kurs_id, 'Skeleton loader animace', '<h2>CSS-only skeleton</h2><p>Skeleton loader zobrazuje zástupné tvary místo obsahu během načítání. Shimmer efekt naznačuje aktivitu.</p><pre><code>@keyframes shimmer {\n  0%   { background-position: -400px 0; }\n  100% { background-position: 400px 0; }\n}\n\n.skeleton {\n  background: #1a1a24;\n  background-image: linear-gradient(\n    90deg,\n    #1a1a24 0%,\n    #252530 40%,\n    #1a1a24 80%\n  );\n  background-size: 800px 100%;\n  animation: shimmer 1.5s infinite linear;\n  border-radius: 8px;\n}\n\n/* Varianty */\n.skeleton-nadpis {\n  width: 60%;\n  height: 24px;\n  margin-bottom: 12px;\n}\n.skeleton-radka {\n  width: 100%;\n  height: 14px;\n  margin-bottom: 8px;\n}\n.skeleton-radka:last-child {\n  width: 80%;\n}\n.skeleton-avatar {\n  width: 48px;\n  height: 48px;\n  border-radius: 50%;\n}\n.skeleton-obrazek {\n  width: 100%;\n  aspect-ratio: 16 / 9;\n}</code></pre><pre><code>&lt;!-- HTML struktura --&gt;\n&lt;div class="karta"&gt;\n  &lt;div class="skeleton skeleton-obrazek"&gt;&lt;/div&gt;\n  &lt;div class="skeleton skeleton-nadpis"&gt;&lt;/div&gt;\n  &lt;div class="skeleton skeleton-radka"&gt;&lt;/div&gt;\n  &lt;div class="skeleton skeleton-radka"&gt;&lt;/div&gt;\n&lt;/div&gt;</code></pre>', 'lesson', 38, 20, 13),

(@kurs_id, 'Container queries prakticky', '<h2>Responzivní karty bez media queries</h2><p>Container queries umožňují komponentě reagovat na prostor, který má k dispozici — ne na šířku okna. To je zásadní pro znovupoužitelnost.</p><pre><code>/* Sidebar definuje kontejner */\n.sidebar {\n  container: card-area / inline-size;\n}\n.main {\n  container: card-area / inline-size;\n}\n\n/* Stejná komponenta, různé chování */\n@container card-area (min-width: 350px) {\n  .karta-komponenta {\n    display: flex;\n    gap: 16px;\n  }\n  .karta-komponenta img {\n    width: 120px;\n    flex-shrink: 0;\n  }\n}\n\n@container card-area (min-width: 500px) {\n  .karta-komponenta {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 24px;\n  }\n}</code></pre><pre><code>&lt;!-- Karta v sidebaru (úzký) --&gt;\n&lt;aside class="sidebar"&gt;\n  &lt;div class="karta-komponenta"&gt;...&lt;/div&gt;\n&lt;/aside&gt;\n\n&lt;!-- Stejná karta v main (široký) --&gt;\n&lt;main class="main"&gt;\n  &lt;div class="karta-komponenta"&gt;...&lt;/div&gt;\n&lt;/main&gt;</code></pre><p>Komponenta se přizpůsobí prostoru — v sidebaru vertikální layout, v main obsahu grid.</p>', 'lesson', 39, 20, 13);


-- ============================================================
-- PROJEKT (sort_order 40)
-- ============================================================

INSERT INTO lessons (course_id, title, content, lesson_type, sort_order, xp_reward, duration_minutes) VALUES
(@kurs_id, 'Kompletní VeVit stránka', '<h2>Projekt: Kompletní VeVit stránka</h2><p>Vytvoř kompletní responzivní stránku s navigací, hero sekcí, gridem karet a postranním panelem. Vše v Tailwind CSS s neomorfním dark theme.</p><pre><code>&lt;!DOCTYPE html&gt;\n&lt;html lang="cs" class="dark"&gt;\n&lt;head&gt;\n  &lt;meta charset="UTF-8"&gt;\n  &lt;meta name="viewport" content="width=device-width, initial-scale=1.0"&gt;\n  &lt;script src="https://cdn.tailwindcss.com"&gt;&lt;/script&gt;\n  &lt;link href="https://fonts.googleapis.com/css2?family=Sora:wght@400;600;700&amp;display=swap" rel="stylesheet"&gt;\n  &lt;script&gt;\n    tailwind.config = {\n      darkMode: "class",\n      theme: {\n        extend: {\n          colors: {\n            vevit: { bg: "#0f0f14", surface: "#1a1a24", accent: "#7c3aed" },\n          },\n          fontFamily: { sora: ["Sora", "sans-serif"] },\n        },\n      },\n    };\n  &lt;/script&gt;\n  &lt;title&gt;VeVit — Vzdělávací platforma&lt;/title&gt;\n&lt;/head&gt;\n&lt;body class="bg-vevit-bg text-gray-200 font-sora min-h-screen"&gt;\n\n  &lt;!-- Navbar --&gt;\n  &lt;nav class="sticky top-0 z-50 bg-vevit-surface/80 backdrop-blur-xl border-b border-vevit-accent/10"&gt;\n    &lt;div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex items-center justify-between h-16"&gt;\n      &lt;h1 class="text-xl font-bold text-vevit-accent"&gt;VeVit&lt;/h1&gt;\n      &lt;div class="hidden md:flex gap-6 text-sm"&gt;\n        &lt;a href="#" class="hover:text-vevit-accent transition"&gt;Kurzy&lt;/a&gt;\n        &lt;a href="#" class="hover:text-vevit-accent transition"&gt;Lektor&lt;/a&gt;\n        &lt;a href="#" class="hover:text-vevit-accent transition"&gt;Kontakt&lt;/a&gt;\n      &lt;/div&gt;\n      &lt;button class="bg-vevit-accent hover:bg-purple-600 px-4 py-2 rounded-lg text-sm font-semibold transition"&gt;\n        Přihlásit\n      &lt;/button&gt;\n    &lt;/div&gt;\n  &lt;/nav&gt;\n\n  &lt;!-- Hero --&gt;\n  &lt;section class="max-w-7xl mx-auto px-4 py-20 text-center"&gt;\n    &lt;h2 class="text-4xl md:text-6xl font-bold mb-6"&gt;\n      Uč se programovat\n      &lt;span class="text-vevit-accent"&gt;interaktivně&lt;/span&gt;\n    &lt;/h2&gt;\n    &lt;p class="text-gray-400 text-lg max-w-2xl mx-auto mb-10"&gt;\n      HTML, CSS, Python a další — s reálnými projekty a okamžitou zpětnou vazbou.\n    &lt;/p&gt;\n    &lt;button class="bg-vevit-accent hover:bg-purple-600 px-8 py-3 rounded-xl text-lg font-semibold transition shadow-lg shadow-vevit-accent/20"&gt;\n      Začít zdarma\n    &lt;/button&gt;\n  &lt;/section&gt;\n\n  &lt;!-- Grid karet --&gt;\n  &lt;section class="max-w-7xl mx-auto px-4 pb-16"&gt;\n    &lt;div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6"&gt;\n      &lt;article class="bg-vevit-surface rounded-2xl p-6 border border-vevit-accent/10 shadow-[6px_6px_12px_#0a0a0f,-6px_-6px_12px_#252530] hover:border-vevit-accent/30 transition"&gt;\n        &lt;h3 class="text-xl font-bold mb-2"&gt;HTML &amp; CSS&lt;/h3&gt;\n        &lt;p class="text-gray-400 mb-4"&gt;Základy webu od struktury po pokročilé CSS.&lt;/p&gt;\n        &lt;span class="text-vevit-accent text-sm font-semibold"&gt;43 lekcí&lt;/span&gt;\n      &lt;/article&gt;\n      &lt;article class="bg-vevit-surface rounded-2xl p-6 border border-vevit-accent/10 shadow-[6px_6px_12px_#0a0a0f,-6px_-6px_12px_#252530] hover:border-vevit-accent/30 transition"&gt;\n        &lt;h3 class="text-xl font-bold mb-2"&gt;Python&lt;/h3&gt;\n        &lt;p class="text-gray-400 mb-4"&gt;Od proměnných po REST API a data science.&lt;/p&gt;\n        &lt;span class="text-vevit-accent text-sm font-semibold"&gt;61 lekcí&lt;/span&gt;\n      &lt;/article&gt;\n      &lt;article class="bg-vevit-surface rounded-2xl p-6 border border-vevit-accent/10 shadow-[6px_6px_12px_#0a0a0f,-6px_-6px_12px_#252530] hover:border-vevit-accent/30 transition"&gt;\n        &lt;h3 class="text-xl font-bold mb-2"&gt;JavaScript&lt;/h3&gt;\n        &lt;p class="text-gray-400 mb-4"&gt;Interaktivita, DOM manipulace a frameworky.&lt;/p&gt;\n        &lt;span class="text-vevit-accent text-sm font-semibold"&gt;Brzy&lt;/span&gt;\n      &lt;/article&gt;\n    &lt;/div&gt;\n  &lt;/section&gt;\n\n  &lt;!-- Layout se sidebarem --&gt;\n  &lt;section class="max-w-7xl mx-auto px-4 pb-20"&gt;\n    &lt;div class="flex flex-col lg:flex-row gap-6"&gt;\n      &lt;aside class="lg:w-72 bg-vevit-surface rounded-2xl p-6 border border-vevit-accent/10 shrink-0"&gt;\n        &lt;h3 class="font-bold mb-4 text-vevit-accent"&gt;Obsah kurzu&lt;/h3&gt;\n        &lt;ul class="space-y-2 text-sm text-gray-400"&gt;\n          &lt;li class="hover:text-white transition cursor-pointer"&gt;1. HTML základy&lt;/li&gt;\n          &lt;li class="hover:text-white transition cursor-pointer"&gt;2. CSS základy&lt;/li&gt;\n          &lt;li class="hover:text-white transition cursor-pointer"&gt;3. Pokročilé CSS+HTML&lt;/li&gt;\n        &lt;/ul&gt;\n      &lt;/aside&gt;\n      &lt;main class="flex-1 bg-vevit-surface rounded-2xl p-8 border border-vevit-accent/10"&gt;\n        &lt;h2 class="text-2xl font-bold mb-4"&gt;Lekce 1: DOCTYPE a struktura&lt;/h2&gt;\n        &lt;p class="text-gray-400 leading-relaxed"&gt;\n          Každý HTML dokument začíná deklarací DOCTYPE, která říká prohlížeči verzi HTML.\n          Následuje kořenový element html, hlavička head a tělo body.\n        &lt;/p&gt;\n      &lt;/main&gt;\n    &lt;/div&gt;\n  &lt;/section&gt;\n\n  &lt;!-- Footer --&gt;\n  &lt;footer class="border-t border-vevit-accent/10 py-8 text-center text-sm text-gray-500"&gt;\n    &amp;copy; 2025 VeVit — Vzdělávací platforma\n  &lt;/footer&gt;\n\n&lt;/body&gt;\n&lt;/html&gt;</code></pre>', 'lesson', 40, 50, 45);


-- ============================================================
-- ZÁVĚREČNÝ KVÍZ (sort_order 41)
-- ============================================================

INSERT INTO lessons (course_id, title, content, lesson_type, sort_order, xp_reward, duration_minutes) VALUES
(@kurs_id, 'Závěrečný kvíz — Celý HTML & CSS kurz', '<p>Závěrečný test pokrývající všechny sekce kurzu HTML & CSS.</p>', 'final_quiz', 41, 200, 25);

SET @qfin = LAST_INSERT_ID();

INSERT INTO quizzes (lesson_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, sort_order) VALUES
(@qfin, 'Co dělá <!DOCTYPE html>?', 'Importuje CSS', 'Deklaruje dokument jako HTML5', 'Vytváří meta tag', 'Definuje kódování', 'b', '<!DOCTYPE html> informuje prohlížeč, že dokument je HTML5 a má být vykreslen ve standards mode.', 1),
(@qfin, 'Který tag je sémantický pro hlavní obsah stránky?', '<div id="main">', '<main>', '<section>', '<content>', 'b', '<main> je sémantický tag pro hlavní obsah stránky — měl by se použít jen jednou.', 2),
(@qfin, 'Jaký je rozdíl mezi box-sizing: content-box a border-box?', 'Žádný', 'content-box přičítá padding+border k šířce, border-box je zahrnuje', 'border-box odstraňuje border', 'content-box je výchozí pro Tailwind', 'b', 'S content-box je width jen obsah, padding a border se přičítají. S border-box je width celková.', 3),
(@qfin, 'Která vlastnost zarovnává flex položky na hlavní ose?', 'align-items', 'justify-content', 'flex-wrap', 'align-self', 'b', 'justify-content zarovnává na hlavní ose (defaultně horizontálně). align-items na příčné ose.', 4),
(@qfin, 'Co znamená fr v CSS Grid?', 'Frame', 'Fraction — zlomek dostupného prostoru', 'Frekvence', 'Full resolution', 'b', 'fr (fraction) je jednotka v Gridu představující podíl volného prostoru — např. 1fr 2fr rozdělí prostor 1:2.', 5),
(@qfin, 'Co je mobile-first přístup?', 'Psát CSS pro mobil a přepisovat min-width dotazy', 'Používat jen max-width dotazy', 'Ignorovat desktop', 'Používat inline styly', 'a', 'Mobile-first = základní styly pro mobil, přepisování pomocí @media (min-width: ...) pro větší obrazovky.', 6),
(@qfin, 'Jak zapíšeš CSS proměnnou a použiješ ji?', '--barva: red; color: var(--barva);', 'var barva = red; color: barva;', '$barva: red; color: $barva;', '@barva: red; color: @barva;', 'a', 'CSS custom properties se definují s -- a čtou přes var() — např. --accent: #7c3aed; color: var(--accent);', 7),
(@qfin, 'Co dělá backdrop-filter: blur(12px)?', 'Rozmaže samotný element', 'Rozmaže obsah za elementem (glassmorphism)', 'Přidá stín', 'Změní průhlednost', 'b', 'backdrop-filter aplikuje filtr na obsah ZA elementem — vytváří efektní glassmorphism/přibližovací efekt.', 8),
(@qfin, 'K čemu slouží aria-label?', 'Skryje element', 'Přidává textový popis pro čtečky obrazovky', 'Mění barvu', 'Přidává tooltip', 'b', 'aria-label poskytuje přístupný textový popis elementu, který čtou asistenční technologie (screen readery).', 9),
(@qfin, 'Co je LCP v Core Web Vitals?', 'Largest Contentful Paint — čas nevětšího vizuálního obsahu', 'Layout Cumulative Problem', 'Lazy Content Preview', 'Last Click Position', 'a', 'LCP (Largest Contentful Paint) měří čas do zobrazení největšího vizuálního obsahu v viewportu — max 2.5s.', 10),
(@qfin, 'Jak přepneš motiv v Tailwind CSS?', 'Změnou class="dark" na html elementu', 'Změnou CSS souboru', 'Přidáním media query', 'Změnou barvy v configu', 'a', 'Tailwind dark: prefix reaguje na třídu "dark" na html elementu — přepínáním této třídy měníš motiv.', 11),
(@qfin, 'Co dělá container-type: inline-size v CSS?', 'Nastavuje šířku kontejneru', 'Umožňuje @container dotazy na šířku kontejneru', 'Vytváří scrollbar', 'Definuje grid', 'b', 'container-type: inline-size deklaruje element jako kontejner pro @container queries, které reagují na jeho šířku.', 12);


